use std::fs

fn digit_val(c: char) -> int {
    let d = c as int
    if d >= 48 && d <= 57 {
        d - 48
    } else if d >= 65 && d <= 90 {
        d - 55
    } else {
        d - 87
    }
}

fn digit_char(v: int) -> char {
    if v < 10 {
        (48 + v) as u8 as char
    } else {
        (55 + v) as u8 as char
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts = line.split_whitespace().map(|s| s.to_string()).collect::<Vec<string>>()
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut n: int = 0
        for c in parts[0].chars() {
            n = n * from + digit_val(c)
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut digits: Vec<char> = []
        while n > 0 {
            digits.push(digit_char(n % to))
            n = n / to
        }
        let mut out = ""
        let mut i = digits.len() as int - 1
        while i >= 0 {
            out = out + digits[i as usize].to_string()
            i -= 1
        }
        println(out)
    }
}

